mapper.select:
SELECT
*
FROM sto_yt_delivery_item
WHERE is_deleted = 0

    AND delivery_id = #{deliveryId}


    AND order_sub_id = #{orderSubId}


    AND order_sub_item_id = #{orderSubItemId}


    AND product_id = #{productId}


    AND specification_id = #{specificationId}

SELECT * FROM ( select syo.id as orderId, syo.code as orderCode, syo.shipping_method, syo.remark as orderRemark, syo.delivery_time as orderDeliveryTime, (select nick_name from sys_user where user_id = syo.sale_employee_id) as sale_employee_name
from sto_yt_delivery_item as sydi left join sal_yt_order_sub as syos on syos.id = sydi.order_sub_id left join sal_yt_order as syo on syo.id = syos.order_id where sydi.is_deleted=0 and sydi.delivery_id = #{id} group by syo.id ) as subquery WHERE 1=1
-- 产品状态筛选
AND subquery.productComplete = #{productComplete}
-- 打包状态筛选
AND subquery.packageComplete = #{packageComplete}

mapper.insert:
INSERT INTO sto_yt_delivery_item (
    delivery_id, order_sub_id, order_sub_item_id, product_id, specification_id, location_id,
    number, shipped_number, category_specification_item_id, category_specification_item_name,
    create_user, create_time, update_user, update_time, tenant_id, is_deleted
) VALUES

    (
        #{item.deliveryId}, #{item.orderSubId}, #{item.orderSubItemId}, #{item.productId}, #{item.specificationId}, #{item.locationId},
        #{item.number}, #{item.shippedNumber}, #{item.categorySpecificationItemId}, #{item.categorySpecificationItemName},
        #{item.createUser}, #{item.createTime}, #{item.updateUser}, #{item.updateTime}, #{item.tenantId}, #{item.isDeleted}
    )

mapper.select:
SELECT sum(sydi.number) as number, (SELECT COALESCE(SUM(syosi_inner.enter_number - IFNULL(committed.total, 0)), 0) FROM sto_yt_delivery_item sydi_inner LEFT JOIN sal_yt_order_sub_item syosi_inner ON syosi_inner.id = sydi_inner.order_sub_item_id LEFT JOIN sal_yt_order_sub syos_inner ON syos_inner.id = sydi_inner.order_sub_id LEFT JOIN ( SELECT sydi_other.order_sub_item_id, SUM(sydi_other.number) as total FROM sto_yt_delivery_item sydi_other JOIN sto_yt_delivery sd_other ON sd_other.id = sydi_other.delivery_id WHERE sydi_other.order_sub_item_id IN ( SELECT order_sub_item_id FROM sto_yt_delivery_item WHERE delivery_id = #{id} AND is_deleted = 0 ) AND sydi_other.delivery_id != #{id} AND sydi_other.is_deleted = 0 AND sd_other.is_deleted = 0 AND sd_other.status > 0 GROUP BY sydi_other.order_sub_item_id ) committed ON committed.order_sub_item_id = sydi_inner.order_sub_item_id WHERE sydi_inner.delivery_id = #{id} AND sydi_inner.is_deleted = 0 AND sydi_inner.product_id = sydi.product_id AND sydi_inner.specification_id = sydi.specification_id AND (sydi_inner.category_specification_item_id = sydi.category_specification_item_id OR (sydi_inner.category_specification_item_id IS NULL AND sydi.category_specification_item_id IS NULL)) AND (sydi_inner.location_id = sydi.location_id OR (sydi_inner.location_id IS NULL AND sydi.location_id IS NULL)) AND syos_inner.order_id = #{orderId} ) as enterNumber, (SELECT COALESCE(SUM(sydbi.number), 0) FROM sto_yt_delivery_box_item sydbi JOIN sto_yt_delivery_box sydb ON sydb.id = sydbi.delivery_box_id left join sal_yt_order_sub_item as syosi2 on syosi2.id = sydbi.order_item_id left join sal_yt_order_sub as syos2 on syos2.id = syosi2.order_sub_id WHERE sydb.delivery_id = #{id} AND sydbi.specification_id = sydi.specification_id and (sydbi.category_specification_item_id = sydi.category_specification_item_id OR (sydbi.category_specification_item_id IS NULL AND sydi.category_specification_item_id IS NULL)) and (sydbi.location_id = sydi.location_id OR (sydbi.location_id IS NULL AND sydi.location_id IS NULL)) AND sydbi.is_deleted = 0
and syos2.order_id = #{orderId}
) as packageNumber, pyp.code as productCode, sydi.product_id,sydi.specification_id,sydi.location_id, (select `description` from pro_yt_product_specification where id = sydi.specification_id) as specificationDesc, (select name from sto_yt_location where id= sydi.location_id) as locationName, -- sydi.order_sub_id, -- (select sub_code from sal_yt_order_sub where id = sydi.order_sub_id) as order_sub_code, sydi.category_specification_item_id,sydi.category_specification_item_name FROM sto_yt_delivery_item as sydi left join pro_yt_product as pyp on pyp.id = sydi.product_id left join sal_yt_order_sub_item as syosi on syosi.id = sydi.order_sub_item_id left join sal_yt_order_sub as syos on syos.id = sydi.order_sub_id WHERE delivery_id = #{id} AND sydi.is_deleted = 0
and syos.order_id = #{orderId}
and order_sub_id=#{orderSubId}
and sydi.specification_id=#{specificationId}
and sydi.specification_id in (select id from pro_yt_product_specification_item where category_specification_item_id in(select id from pro_yt_category_specification_item where value like ('%',#{specificationName},'%') and is_deleted=0) and is_deleted=0) and is_deleted=0
and pyp.code like concat('%',#{productCode},'%')
and sydi.category_specification_item_id=#{categorySpecificationItemId}
GROUP BY product_id, specification_id, category_specification_item_id,category_specification_item_name,location_id -- ORDER BY sydi.create_time

SELECT sydi.order_sub_item_id AS orderSubItemId, COALESCE(SUM(sydi.number), 0) AS totalNumber FROM sto_yt_delivery_item sydi INNER JOIN sto_yt_delivery syd ON syd.id = sydi.delivery_id WHERE sydi.is_deleted = 0 AND syd.is_deleted = 0 AND syd.status = '1' AND sydi.order_sub_item_id IN
#{orderSubItemId}
GROUP BY sydi.order_sub_item_id

SELECT sydi.*, (select code from pro_yt_product where id = sydi.product_id) as productCode FROM sto_yt_delivery_item as sydi LEFT JOIN sal_yt_order_sub as syos ON syos.id = sydi.order_sub_id WHERE syos.order_id IN
#{orderId}
AND sydi.is_deleted = 0

select sum(number)
from sto_yt_delivery_item
where order_sub_id = #{orderSubId}
  and delivery_id = #{deliveryId}
and is_deleted = 0
